// TH14 v1.00b Extra 奖励波：MainSub04 B组（st07.ecl.txt:813-821）
// 6 对 ECir01（816 enmCreateMF 镜像 / 818 enmCreateF 普通），依赖 ECir01:94-127、ECir01_at:129-157。
// 独立奖励波口径：无 boss0，F/MF 门全部通过；不带上游 GirlC01 与 A/C/D 组。

const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;

// 源 ECir01 入场两段 Hermite（REL 层，源 114-119）。ABS 恒零、无残余速度，
// 因此目标用绝对位置表达最终位置；两段都用 Hermite 槽 0/1 逐帧写回。
async sub ecir01(s: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);            // 源 103 setHurtbox(24,24)：普通圆半径 12
    set_hitbox(8fx);              // 源 104 setHitbox(16,16)：普通圆半径 8
    // 源 114 movePosRel(-192*A, 0)：A 由镜像位给出（MF→-1，F→+1）
    move_to(0, -192fx * s, 0fx, EASE_LINEAR);
    // 源 115 moveBezierRel(120, 256A,-30, 160A,128, 0,0)：终点 (-32A,128)
    hermite_start(0, -192fx * s, -32fx * s, 256fx * s, 0fx, 120);
    hermite_start(1, 0fx, 128fx, -30fx, 0fx, 120);
    for k in 0..120 {
        wait(1);
        move_to(1, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // 源 116-117 wait(120)/flagClear(15)：入场无敌位由 set_invuln(65535) 外壳覆盖
    // 源 119 moveBezierRel(120, 0,0, -220A,192, -200A,-228)：终点 (-252A,320)
    hermite_start(0, -32fx * s, -252fx * s, 0fx, -200fx * s, 120);
    hermite_start(1, 128fx, 320fx, 0fx, -228fx, 120);
    spawn ecir01_at(s);           // 源 120 @ECir01_at(%A) async；次帧首跑
    for k2 in 0..120 {
        wait(1);
        move_to(1, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // 源 121-125 主任务 wait(1000) 常驻，不返回
    loop { wait(1); }
}

// 源 ECir01_at：两轮（138 C=1），每轮 32 次（142 D=32），每 10 帧沿 B 与 B-π 各一条激光。
// 源 132-137 etNew/etSprite/etAngle/etSpeed/laserNew：激光参数折叠到每次 laser() 调用。
async sub ecir01_at(s: fx) {
    var a: int = s as int;                                   // 源 99-101 %A = ±1
    for wave in 0..2 {
        // 源 141 %B = ANGLE_PLAYER - π/4 + 0.17453292*RANDF2（每轮取样一次）
        var b: int = (aim_player() as int) - 8192 + (rand(65536) - 32768) / 18;
        for r in 0..32 {
            // 源 145-148：etAngle(0,B); laserOn；etAngle(0,B-π); laserOn
            // 源 136 laserNew(0, 0, 128, 0, 14)：Line 判定段 0.1L..0.9L、宽度 14→半高 3.5
            var h: int = laser(2, $self_x, $self_y, b as angle, 0fx, 7fx, 0, 9999, 0);
            lz_start(h, 12.8fx);
            lz_speed(h, 5fx, 102.4fx);                       // 源 etSpeed 5：棒长 = 0.8*128
            var h2: int = laser(2, $self_x, $self_y, (b - 32768) as angle, 0fx, 7fx, 0, 9999, 0);
            lz_start(h2, 12.8fx);
            lz_speed(h2, 5fx, 102.4fx);
            b = b + a * 3641;                                // 源 149 %B += %A*2π/18
            wait(10);                                        // 源 150
        }
        wait(60);                                            // 源 153
    }
}

// 源 813 $B=6；816/818 每 90 帧一对，共 6 对 12 只。
async sub source_pair() {
    wait(OPENING_BUFFER);
    for i in 0..6 {
        _ = spawn_enemy(0fx, 0fx, 160, 0, 1000, 0, ecir01(-1fx));  // 源 816 MF：子镜像1
        wait(90);                                                  // 源 817
        _ = spawn_enemy(0fx, 0fx, 160, 0, 1000, 0, ecir01(1fx));   // 源 818 F：子镜像0
        wait(90);                                                  // 源 819
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, source_pair, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
